(()=>{document.querySelectorAll('[data-carousel]').forEach(root=>{const viewport=root.querySelector('.carousel-viewport'),track=root.querySelector('.carousel-track'),prev=root.querySelector('[data-carousel-prev]'),next=root.querySelector('[data-carousel-next]'),dots=root.querySelector('.carousel-dots');if(!track)return;const originals=[...track.children];const count=originals.length;if(count<2){prev?.setAttribute('hidden','');next?.setAttribute('hidden','');return}const before=originals.map(n=>n.cloneNode(true)),after=originals.map(n=>n.cloneNode(true));before.reverse().forEach(n=>track.prepend(n));after.forEach(n=>track.append(n));let index=count,step=0,moving=false,timer;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const getStep=()=>{const card=track.children[0],gap=parseFloat(getComputedStyle(track).gap)||0;step=card.getBoundingClientRect().width+gap};const set=(animate=true)=>{track.style.transition=animate&&!reduced?'transform .65s cubic-bezier(.22,.61,.36,1)':'none';track.style.transform=`translate3d(${-index*step}px,0,0)`;updateDots()};const updateDots=()=>{const logical=((index-count)%count+count)%count;[...dots.children].forEach((d,i)=>d.classList.toggle('active',i===logical))};for(let i=0;i<count;i++){const d=document.createElement('span');d.className='carousel-dot';dots.appendChild(d)}const move=delta=>{if(moving)return;moving=true;index+=delta;set(true)};track.addEventListener('transitionend',()=>{if(index>=count*2){index-=count;set(false)}else if(index<count){index+=count;set(false)}moving=false});prev?.addEventListener('click',()=>{move(-1);restart()});next?.addEventListener('click',()=>{move(1);restart()});const start=()=>{if(reduced)return;clearInterval(timer);timer=setInterval(()=>move(1),Number(root.dataset.autoplay)||5200)};const stop=()=>clearInterval(timer);const restart=()=>{stop();start()};root.addEventListener('mouseenter',stop);root.addEventListener('mouseleave',start);root.addEventListener('focusin',stop);root.addEventListener('focusout',start);document.addEventListener('visibilitychange',()=>document.hidden?stop():start());let sx=0;viewport.addEventListener('pointerdown',e=>sx=e.clientX);viewport.addEventListener('pointerup',e=>{const dx=e.clientX-sx;if(Math.abs(dx)>45){move(dx>0?-1:1);restart()}});new ResizeObserver(()=>{getStep();set(false)}).observe(viewport);getStep();set(false);start()})})();
